$ProgressPreference='SilentlyContinue';$profile='C:\Users\Acer\.ssh-relay-pro-5.7-isolated';$s=Get-Content "$profile\client-runtime.json" -Raw|ConvertFrom-Json;$a=Get-Content "$profile\far\agent-runtime.json" -Raw|ConvertFrom-Json;$events=@();foreach($f in Get-ChildItem "$profile\logs\runtime-*.jsonl"){if($f.Name -match "-$($s.clientPid)-|-$($s.pid)-|-$($a.pid)-"){foreach($line in Get-Content $f.FullName){try{$e=$line|ConvertFrom-Json;if($e.event -in @('event_loop_stall','uncaught_exception','unhandled_rejection','process_exit','guardian_finish')){$events+=@{event=$e.event;time=$e.time;delayMs=$e.delayMs;role=$e.role;exitCode=$e.exitCode}}}catch{}}}}
@{guiPid=$s.clientPid;supervisorPid=$s.pid;agentPid=$a.pid;heartbeatAgeMs=([DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()-$s.heartbeatAt);events=$events;processes=@(Get-Process -Id $s.clientPid,$s.pid,$a.pid|Select Id,Responding,CPU,StartTime,WorkingSet64);logBytes=(Get-ChildItem "$profile\logs" -File|Measure-Object Length -Sum).Sum}|ConvertTo-Json -Compress -Depth 5
